const body = $('Search Packages Webhook').first().json.body ?? {};
const dest = String(body.destination ?? '').trim().toLowerCase();
const style = String(body.travel_style ?? '').trim().toLowerCase();
const groupSize = Math.max(1, Math.round(Number(body.group_size) || 1));
const budgetPP = (Number(body.budget) || 0) / groupSize;
if (!dest || budgetPP <= 0) return [{ json: { found: false, count: 0, packages: [], upsell: null, message: 'I still need the destination, the total budget and the number of travellers.' } }];

const rows = $input.all().map((i) => i.json).filter((r) => r.package_id && String(r.active ?? 'TRUE').toLowerCase() !== 'false');
const match = rows.filter((r) => { const d = String(r.destination ?? '').toLowerCase(); return d && (d.includes(dest) || dest.includes(d)); });
const shape = (r) => ({ package_id: r.package_id, title: r.title, duration_days: Number(r.duration_days), price_per_person: Number(r.price_per_person), total_price: Number(r.price_per_person) * groupSize, category: r.category, inclusions: r.inclusions });
const score = (r) => Number(r.price_per_person) / 1000 + (style && String(r.category ?? '').toLowerCase().includes(style) ? 100 : 0);

const packages = match.filter((r) => Number(r.price_per_person) <= budgetPP).sort((a, b) => score(b) - score(a)).slice(0, 3).map(shape);
const up = match.filter((r) => Number(r.price_per_person) > budgetPP && Number(r.price_per_person) <= budgetPP * 1.2).sort((a, b) => a.price_per_person - b.price_per_person)[0];
const upsell = up ? shape(up) : null;

let message;
if (packages.length) {
  message = 'I found ' + packages.length + ' package(s) within budget: ' + packages.map((p) => p.title + ' (' + p.duration_days + ' days, $' + p.price_per_person + ' per person)').join('; ') + '.';
  if (upsell) message += ' A slightly higher option: ' + upsell.title + ' at $' + upsell.price_per_person + ' per person.';
} else if (upsell) {
  message = 'Nothing fits the exact budget, but ' + upsell.title + ' is close at $' + upsell.price_per_person + ' per person.';
} else {
  message = 'No package matches that destination and budget. Offer a consultant call if the caller still wants help.';
}
return [{ json: { found: packages.length > 0 || !!upsell, count: packages.length, packages, upsell, message } }];

const body = $input.first().json.body ?? {};
const required = ['name', 'phone_number', 'email', 'package_id', 'travel_date', 'group_size'];
const missing = required.filter((field) => body[field] === undefined || body[field] === null || String(body[field]).trim() === '');
if (missing.length) throw new Error(`Missing required booking fields: ${missing.join(', ')}`);
if (body.caller_confirmed !== true) throw new Error('Booking requires explicit caller confirmation.');
if (!String(body.email).includes('@')) throw new Error('A valid email is required.');
if (!/^\d{4}-\d{2}-\d{2}$/.test(String(body.travel_date)) || String(body.travel_date) < $now.toFormat('yyyy-LL-dd')) throw new Error('travel_date must be a future date in YYYY-MM-DD format.');
return $input.all();

const body = $('Book Package Webhook').first().json.body ?? {};
const id = String(body.package_id ?? '').trim().toUpperCase();
const pkg = $input.all().map((i) => i.json).find((r) => String(r.package_id ?? '').trim().toUpperCase() === id && String(r.active ?? 'TRUE').toLowerCase() !== 'false');
if (!pkg) return [{ json: { found: false } }];
return [{ json: { found: true, package_id: pkg.package_id, package_title: pkg.title, destination: pkg.destination, price_per_person: pkg.price_per_person, duration_days: pkg.duration_days, inclusions: pkg.inclusions, best_season: pkg.best_season, visa_note: pkg.visa_note } }];

const body = $input.first().json.body ?? {};
const action = String(body.action ?? '').toLowerCase();
if (!['cancel', 'update'].includes(action)) throw new Error('action must be cancel or update.');
if (!body.booking_id || !body.phone_number) throw new Error('booking_id and phone_number are required.');
if (body.caller_confirmed !== true) throw new Error('Changes require explicit caller confirmation.');
if (action === 'update' && !body.new_travel_date && !body.new_group_size) throw new Error('new_travel_date or new_group_size is required for updating.');
if (body.new_travel_date && (!/^\d{4}-\d{2}-\d{2}$/.test(String(body.new_travel_date)) || String(body.new_travel_date) < $now.toFormat('yyyy-LL-dd'))) throw new Error('new_travel_date must be a future date in YYYY-MM-DD format.');
return $input.all();

const body = $('Manage Booking Webhook').first().json.body ?? {};
const last10 = (v) => { const d = String(v ?? '').replace(/\D/g, ''); return d.length > 10 ? d.slice(-10) : d; };
const id = String(body.booking_id ?? '').trim().toUpperCase();
const phone = last10(body.phone_number);
const match = $input.all().find(({ json }) =>
  String(json.booking_id ?? '').trim().toUpperCase() === id &&
  last10(json.phone_number) === phone &&
  String(json.status ?? '').trim().toLowerCase() !== 'cancelled');
if (!match) return [{ json: { found: false } }];
return [{ json: { ...match.json, found: true, row_number: match.json.row_number } }];

const body = $('Manage Booking Webhook').first().json.body ?? {};
const old = $input.first().json;
const groupSize = body.new_group_size ? Math.max(1, Math.round(Number(body.new_group_size))) : Number(old.group_size);
return [{ json: {
  row_number: old.row_number,
  travel_date: body.new_travel_date || old.travel_date,
  group_size: groupSize,
  total_price: groupSize * Number(old.price_per_person),
  updated_at: $now.toISO(),
} }];
